<?php
if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/config/conexao.php'; require_once __DIR__.'/auth/verifica_login.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$fornecedores=$pdo->query("SELECT id,COALESCE(NULLIF(nome_fantasia,''),razao_social) nome,tipo_fornecimento,status FROM fornecedores ORDER BY nome")->fetchAll();
$editarTipo=strtoupper($_GET['editar_tipo']??''); $editarId=(int)($_GET['editar_id']??0); $itemEditar=null;
if($editarId>0 && in_array($editarTipo,['PRODUTO','MATERIAL'],true)){
    if($editarTipo==='PRODUTO') $q=$pdo->prepare("SELECT p.id,p.codigo,p.sku,p.nome,p.unidade_medida,p.preco_custo,p.preco_venda,p.estoque_minimo_local,p.fornecedor_id FROM produtos p WHERE p.id=? AND p.status='ATIVO'");
    else $q=$pdo->prepare("SELECT s.id,s.codigo,s.nome,s.unidade_medida,s.estoque_minimo,fs.fornecedor_id FROM suprimentos s LEFT JOIN fornecedor_suprimentos fs ON fs.suprimento_id=s.id AND fs.fornecedor_preferencial=1 WHERE s.id=? AND s.status='ATIVO'");
    $q->execute([$editarId]); $itemEditar=$q->fetch(PDO::FETCH_ASSOC) ?: null;
    if(!$itemEditar){$editarTipo='';$editarId=0;}
}
$produtos=$pdo->query("SELECT p.id,p.codigo,p.sku,p.nome,p.fornecedor_id,'PRODUTO' tipo_item,'Produto para Venda' tipo,COALESCE(NULLIF(f.nome_fantasia,''),f.razao_social) fornecedor FROM produtos p LEFT JOIN fornecedores f ON f.id=p.fornecedor_id WHERE p.status='ATIVO' ORDER BY p.nome LIMIT 50")->fetchAll();
$suprimentos=$pdo->query("SELECT s.id,s.codigo,s.nome,fs.fornecedor_id,'MATERIAL' tipo_item,'Material de Uso' tipo,COALESCE(NULLIF(f.nome_fantasia,''),f.razao_social) fornecedor FROM suprimentos s LEFT JOIN fornecedor_suprimentos fs ON fs.suprimento_id=s.id AND fs.fornecedor_preferencial=1 LEFT JOIN fornecedores f ON f.id=fs.fornecedor_id WHERE s.status='ATIVO' ORDER BY s.nome LIMIT 50")->fetchAll();
$msg=$_SESSION['itens_msg']??'';$tipoMsg=$_SESSION['itens_tipo']??'sucesso';unset($_SESSION['itens_msg'],$_SESSION['itens_tipo']);
require_once __DIR__.'/includes/header.php'; require_once __DIR__.'/includes/sidebar.php';
?>
<div class="main"><div class="topbar"><div><h1>Produtos</h1><p>Cadastre produtos de venda ou materiais de uso com os campos adequados para cada finalidade.</p></div></div><div class="content"><div class="suprimentos-container">
<?php if($msg): ?><div class="suprimentos-message <?=h($tipoMsg)?>"><?=h($msg)?></div><?php endif; ?>
<div class="suprimentos-form-box"><h2><?= $itemEditar ? 'Editar item' : 'Cadastrar produto ou material' ?></h2><p class="form-help">Selecione o tipo. O sistema mostra somente os campos necessários para aquela finalidade.</p>
<form method="post" action="controllers/itens_controller.php" id="form-item"><input type="hidden" name="acao" value="<?= $itemEditar ? 'editar_item' : 'salvar_item' ?>"><?php if($itemEditar): ?><input type="hidden" name="item_id" value="<?=$editarId?>"><input type="hidden" name="tipo_original" value="<?=h($editarTipo)?>"><?php endif; ?>
<div class="suprimentos-form-grid">
<div class="full"><label>Tipo de item *</label><select name="tipo_item" id="tipo_item" required><option value="">Selecione</option><option value="PRODUTO" <?=($itemEditar && $editarTipo==='PRODUTO')?'selected':''?>>Produto para Venda</option><option value="MATERIAL" <?=($itemEditar && $editarTipo==='MATERIAL')?'selected':''?>>Material de Uso</option></select></div>
<div class="full"><label>Fornecedor *</label><select name="fornecedor_id" id="fornecedor_id" required disabled><option value="">Selecione primeiro o tipo de item</option><?php foreach($fornecedores as $f): ?><option value="<?=$f['id']?>" data-tipo="<?=h($f['tipo_fornecimento'])?>" data-status="<?=h($f['status'])?>" <?=($itemEditar && (int)($itemEditar['fornecedor_id']??0)===(int)$f['id'])?'selected':''?>><?=h($f['nome'])?><?=($f['status']==='INATIVO')?' (inativo — cadastro existente)':''?></option><?php endforeach; ?></select><small class="form-help">A lista considera apenas fornecedores ativos compatíveis com o tipo selecionado.</small></div>
<div><label>Código <span id="codigo-obrigatorio">*</span></label><input name="codigo" id="codigo" placeholder="Ex.: PRD-001" value="<?=h($itemEditar['codigo']??'')?>" required></div><div><label>Nome *</label><input name="nome" required value="<?=h($itemEditar['nome']??'')?>"></div><div><label>Unidade *</label><select name="unidade_medida"><?php foreach(['UN','KG','G','M','M2','L','CX','PCT','ROLO'] as $un): ?><option value="<?=$un?>" <?=($itemEditar && ($itemEditar['unidade_medida']??'UN')===$un)?'selected':''?>><?=$un?></option><?php endforeach; ?></select></div>
<div id="produto-campos" class="full" style="display:none"><div class="suprimentos-form-grid"><div><label>SKU</label><input name="sku" value="<?=h($itemEditar['sku']??'')?>"></div><div><label>Valor pago / custo (R$) *</label><input type="number" step="0.01" min="0" name="preco_custo" value="<?=h($itemEditar['preco_custo']??'0')?>" required></div><div><label>Valor de venda (R$) *</label><input type="number" step="0.01" min="0" name="preco_venda" value="<?=h($itemEditar['preco_venda']??'0')?>" required></div><div><label>Estoque mínimo local</label><input type="number" step="0.01" min="0" name="estoque_minimo_local" value="<?=h($itemEditar['estoque_minimo_local']??'0')?>"></div></div></div>
<div id="material-campos" class="full" style="display:none"><div class="suprimentos-form-grid"><div><label>Estoque mínimo</label><input type="number" step="0.01" min="0" name="estoque_minimo" value="<?=h($itemEditar['estoque_minimo']??'0')?>"></div></div></div>
</div><button class="btn btn-pri"><?= $itemEditar ? 'Salvar alterações' : 'Cadastrar item' ?></button><?php if($itemEditar): ?> <a class="btn btn-sec" href="cadastro_itens.php">Cancelar edição</a><?php endif; ?></form></div>
<div class="card"><div class="section-header"><div><h2>Últimos itens cadastrados</h2><p>O formulário se adapta ao tipo de item selecionado.</p></div></div><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Tipo</th><th>Item</th><th>Fornecedor</th><th>Identificação</th><th>Ações</th></tr></thead><tbody><?php foreach(array_merge($produtos,$suprimentos) as $i): ?><tr><td><span class="estoque-tag <?=strpos($i['tipo'],'Produto')!==false?'ok':'atencao'?>"><?=h($i['tipo'])?></span></td><td><strong><?=h($i['nome'])?></strong></td><td><?=h($i['fornecedor']??'—')?></td><td><?=h($i['codigo']??'—')?><?=!empty($i['sku'])?' · SKU '.h($i['sku']):''?></td><td><a class="btn btn-salvar" href="cadastro_itens.php?editar_tipo=<?=h($i['tipo_item'])?>&amp;editar_id=<?=(int)$i['id']?>">Editar</a> <form style="display:inline" method="post" action="controllers/itens_controller.php" onsubmit="return confirm('Inativar este item? Ele deixará de aparecer nos novos cadastros, mas o histórico será preservado.')"><input type="hidden" name="acao" value="inativar_item"><input type="hidden" name="tipo_item" value="<?=h($i['tipo_item'])?>"><input type="hidden" name="item_id" value="<?=(int)$i['id']?>"><button class="btn btn-cancelar" type="submit">Inativar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
</div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){const t=document.getElementById('tipo_item'),p=document.getElementById('produto-campos'),m=document.getElementById('material-campos'),f=document.getElementById('fornecedor_id'),codigo=document.getElementById('codigo');function a(){const produto=t.value==='PRODUTO',material=t.value==='MATERIAL';p.style.display=produto?'block':'none';m.style.display=material?'block':'none';p.querySelectorAll('input').forEach(x=>{x.disabled=!produto;x.required=produto&&(x.name==='preco_custo'||x.name==='preco_venda');});m.querySelectorAll('input').forEach(x=>x.disabled=!material);const original=<?=json_encode((int)($itemEditar['fornecedor_id']??0))?>;const tipoOriginal=<?=json_encode($editarTipo)?>;codigo.required=produto;f.disabled=!t.value;let compativeis=0;Array.from(f.options).forEach((o,i)=>{if(i===0){o.hidden=false;o.disabled=false;return;}const tipos=(o.dataset.tipo||'').split(',');const ok=(o.dataset.status!=='INATIVO')&&(tipos.includes('AMBOS')||(produto&&tipos.includes('PRODUTO'))||(material&&tipos.includes('MATERIAL')))||(t.value===tipoOriginal&&original>0&&Number(o.value)===original);o.hidden=!ok;o.disabled=!ok;if(ok)compativeis++;});if(!t.value){f.options[0].text='Selecione primeiro o tipo de item';f.value='';}else{f.options[0].text=compativeis?'Selecione um fornecedor':'Nenhum fornecedor ativo compatível';if(f.selectedOptions.length&&f.selectedOptions[0].disabled)f.value='';}}t.addEventListener('change',a);a();});</script>
<?php require_once __DIR__.'/includes/footer.php'; ?>
